script:
export const meta = {
  name: 'review_loop',
  description: 'Actor-Critic review→fix→re-review loop with per-file chunked fan-out, adversarial verification, severity gating, bounded convergence',
  phases: [{ title: 'Scope' }, { title: 'Converge' }, { title: 'Report' }],
}

// ---- Config (overridable via args; CLI key=value arrive as strings) ----
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d }
const scope         = (args && args.scope) || (args && args._) || 'the current branch vs its merge-base with main, else staged, else HEAD'
const maxRounds     = num(args && args.maxRounds, 5)
const reviewers     = num(args && args.reviewers, 2)
const threshold     = num(args && args.threshold, 0.5)
// Per-chunk TARGET size (not a hard ceiling): each critic lane reviews at most ~this many diff lines.
const chunkTarget   = num((args && args.chunkTargetLines) || (args && args.maxChunkLines), 400)
const maxChunks     = num(args && args.maxChunks, 12)   // caps chunks*lanes agents per round
let gate = (args && args.severityGate) || ['blocker', 'high']
if (typeof gate === 'string') gate = gate.split(',').map((s) => s.trim()).filter(Boolean)

const findingSchema = {
  type: 'object',
  properties: { findings: { type: 'array', items: { type: 'object', properties: {
    id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'high', 'medium', 'suggestion'] },
    category: { type: 'string', enum: ['security', 'correctness', 'performance', 'maintainability'] },
    location: { type: 'string' }, description: { type: 'string' }, evidence: { type: 'string' },
    repro_test: { type: 'string' }, boundary_owner: { type: 'string', enum: ['current', 'server', 'external'] },
    confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
  }, required: ['id', 'severity', 'category', 'location', 'description', 'boundary_owner'] } } },
  required: ['findings'],
}

// ---- Phase 1: resolve scope + per-file sizes, then pack into bounded chunks ----
phase('Scope')
const scan = await agent(
  'Resolve review scope: ' + scope + '. Determine the git diff command (e.g. "git diff main...HEAD", ' +
  '"git diff --staged", or "git show HEAD") WITHOUT file paths, and list changed files with each file\'s ' +
  'added+removed line count. Return diffCmd, files [{path, lineCount}], and totalLines.',
  { tier: 'small', label: 'scope + sizes', schema: { type: 'object', properties: {
      diffCmd: { type: 'string' },
      files: { type: 'array', items: { type: 'object', properties: { path: { type: 'string' }, lineCount: { type: 'number' } }, required: ['path', 'lineCount'] } },
      totalLines: { type: 'number' }
    }, required: ['diffCmd', 'files', 'totalLines'] } })

// Pack files into <= maxChunks chunks, each ~chunkTarget lines (a lone oversized file gets its own chunk).
const perChunk = Math.max(chunkTarget, Math.ceil((scan.totalLines || 1) / maxChunks))
const chunks = []
let cur = [], curLines = 0
for (const f of scan.files) {
  if (cur.length && curLines + f.lineCount > perChunk) { chunks.push(cur); cur = []; curLines = 0 }
  cur.push(f); curLines += f.lineCount
}
if (cur.length) chunks.push(cur)
const oversizedFiles = scan.files.filter((f) => f.lineCount > perChunk).map((f) => f.path)
log('scope: ' + scan.files.length + ' files, ' + scan.totalLines + ' lines -> ' + chunks.length + ' chunk(s) of ~' + perChunk + ' lines')

const RULES =
  ' RULES: Comment ONLY on the files in this chunk plus at most one hop of direct dependencies. Flag issues; do NOT rewrite code. ' +
  'Severity blocker/high = crashes, security, logic bugs, measurable perf/arch regressions; medium/suggestion = style, micro-opts, speculative edge cases. ' +
  'Set boundary_owner=current only if the fix belongs in THIS diff. For every blocker/high include a concrete repro_test that fails on current behavior. Quote evidence.'

// One critic lane over one chunk: fetches its own scoped diff via git (keeps context small & high-signal).
const laneOnChunk = (persona, tier, paths, tag) =>
  agent(persona + ' Obtain this chunk\'s diff by running: ' + scan.diffCmd + ' -- ' + paths.join(' ') +
        '\nReview only those files (+ one hop).' + RULES,
        { tier, label: tag, schema: findingSchema })

// ---- Phase 2: bounded Actor-Critic convergence loop (chunked fan-out per round) ----
phase('Converge')
let lastSurvivors = []
let roundsRun = 0
const tracked = []
const fixLog = []

const found = await loopUntilDry({
  maxRounds, consecutiveEmpty: 2, key: (f) => f.id,
  round: async (r) => {
    roundsRun = r + 1
    // CRITIC: fan out chunks x lanes; each lane isolated + scope-locked to its chunk.
    const perChunkResults = await parallel(chunks.map((chunk, ci) => async () => {
      const paths = chunk.map((f) => f.path)
      const lanes = await parallel([
        () => laneOnChunk('Read the skill file at ~/.agents/skills/thermo-nuclear-code-quality-review/SKILL.md (expand ~ to your home dir) and apply it as a MAINTAINABILITY critic.',
                          'big', paths, 'maint c' + ci + ' r' + roundsRun),
        () => laneOnChunk('You are a CORRECTNESS critic: trace critical paths; logic bugs, missing authz, boundary/edge errors.',
                          'big', paths, 'correct c' + ci + ' r' + roundsRun),
        () => laneOnChunk('You are a SECURITY critic: injection, secrets, authz, unsafe handling of untrusted input.',
                          'medium', paths, 'sec c' + ci + ' r' + roundsRun),
      ])
      return lanes.filter(Boolean).flatMap((l) => (l && l.findings) || [])
    }))
    const all = perChunkResults.flat()

    // CLASSIFY: loop-drivers vs tracked-for-later
    const gated = []
    for (const f of all) {
      if (gate.indexOf(f.severity) >= 0 && f.boundary_owner === 'current') gated.push(f)
      else tracked.push(f)
    }
    if (!gated.length) { lastSurvivors = []; return [] }

    // VERIFY: adversarial skeptics must REFUTE; only survivors proceed
    const checks = await parallel(gated.map((f) => () =>
      verify('Category ' + f.category + ' at ' + f.location + ': ' + f.description +
             '\nClaimed repro: ' + (f.repro_test || '(none)') +
             '\nREAL only if the repro would truly fail on current behavior and the fix belongs in this diff.',
             { reviewers, threshold, lens: [f.category, 'is this edge case already implicitly handled?'] })))
    const survivors = gated.filter((_f, i) => checks[i] && checks[i].real)
    lastSurvivors = survivors
    if (!survivors.length) return []

    // ACTOR: single fixer holds fix authority; fixes survivors ONLY, adds failing->passing tests, stays in scope
    const fix = await agent(
      'You are the fixer. Apply MINIMAL fixes for ONLY these verified blockers, add a test that fails before / passes after each, ' +
      'stay within the diff scope, then report what changed.\n\n' + JSON.stringify(survivors),
      { tier: 'big', label: 'fix r' + roundsRun })
    fixLog.push({ round: roundsRun, fixed: survivors.length, summary: fix })
    return survivors
  },
})

// ---- Phase 3: report + verdict + escalation ----
phase('Report')
const converged = lastSurvivors.length === 0 && roundsRun < maxRounds
const hitCap    = roundsRun >= maxRounds && lastSurvivors.length > 0
const verdict = converged ? 'CONVERGED CLEAN'
              : hitCap    ? 'STOPPED AT CAP — escalate to human'
              :             'STOPPED — no new blockers (possible oscillation on remaining items)'

const report = await agent(
  'Write a concise final report: verdict, chunking summary, per-round trajectory, resolution rate (fixed/total gated), ' +
  'unresolved items to escalate, and the tracked-for-later list. Do NOT re-litigate resolved items.\n\n' +
  'VERDICT: ' + verdict + '\nCHUNKS: ' + chunks.length + ' (~' + perChunk + ' lines each)' +
  '\nOVERSIZED FILES (single-file context risk): ' + JSON.stringify(oversizedFiles) +
  '\nROUNDS: ' + roundsRun + '\nFIX LOG:\n' + JSON.stringify(fixLog) +
  '\nUNRESOLVED:\n' + JSON.stringify(lastSurvivors) + '\nTRACKED:\n' + JSON.stringify(tracked),
  { tier: 'big', label: 'synthesis' })

return { verdict, roundsRun, chunks: chunks.length, oversizedFiles, totalFixed: found.length, unresolved: lastSurvivors, tracked, report }
